fun <T> raEq(label: String, got: T, want: T) = raCp(got == want, label, "got $got, want $want")
inline fun raTry(label: String, f: () -> Unit) { try { f() } catch (e: Throwable) { println("::cp::FAIL::$label::\${e::class.java.simpleName}: \${e.message}") } }
