 = false; try { b.at(2); } catch (const std::out_of_range&) { t = true; } ra_cp(t, \"at() throws out_of_range\"); });\n    ra_try(\"move leaves source empty\", [] { Buffer a(3); a.at(0) = 7; Buffer b(std::move(a)); ra_cp(b.size() == 3 && a.size() == 0 && b.at(0) == 7, \"move leaves source empty\"); });\n    ra_cp(!std::is_copy_constructible_v<Buffer> && std::is_nothrow_move_constructible_v<Buffer> && std::is_nothrow_move_assignable_v<Buffer>, \"Buffer is move-only and noexcept\");\n#ifdef TEST\n    int before = ra_gtest::failures(); std::size_t n = ra_gtest::cases().size();\n    for (auto& c : ra_gtest::cases()) c.fn();\n    ra_cp(n > 0 && ra_gtest::failures() == before, \"Your TESTs pass\", std::to_string(ra_gtest::failures() - before) + \" failures in \" + std::to_string(n) + \" tests\");\n#else\n    ra_cp(false, \"Your TESTs pass\", \"add #include <gtest/gtest.h> and a TEST(...)\");\n#endif\n}\n","cpp2":"// @cp score 95 | score 90 | score 60 | score 59 | score 30 | score 0 | Level is a scoped enum\n#include <type_traits>\n//@@PRELUDE@@\n//@@USER@@\nint main() {\n    int s[] = {95, 90, 60, 59, 30, 0};\n    const char* w[] = {\"CRITICAL\", \"CRITICAL\", \"HIGH\", \"MEDIUM\", \"MEDIUM\", \"LOW\"};\n    for (int i = 0; i < 6; i++) { std::string l = \"score \" + std::to_string(s[i]); ra_try(l, [&] { ra_eq(l, std::string(name(classify(s[i]))), std::string(w[i])); }); }\n    ra_cp(std::is_enum_v<Level> && !std::is_convertible_v<Level, int>, \"Level is a scoped enum\", \"use enum class\");\n}\n","cpp3":"// @cp tally counts | tally empty\n//@@PRELUDE@@\n//@@USER@@\nint main() {\n    ra_try(\"tally counts\", [] { auto t = tally({\"a\", \"b\", \"a\"}); ra_cp(t.size() == 2 && t[\"a\"] == 2 && t[\"b\"] == 1, \"tally counts\", \"size \" + std::to_string(t.size())); });\n    ra_try(\"tally empty\", [] { ra_eq(\"tally empty\", tally({}).size(), std::size_t(0)); });\n}\n","cpp4":"// @cp count_words | count_words of blank text | redact edits in place | scan default port is 443\n//