      var n = (a << 18) | (b << 12) | ((c < 0 ? 0 : c) << 6) | (d < 0 ? 0 : d);
      o += String.fromCharCode((n >> 16) & 255);
      if (c >= 0) o += String.fromCharCode((n >> 8) & 255);
      if (d >= 0) o += String.fromCharCode(n & 255);
    }
    return o;
  };
