  var ent = function (s) { return s.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, "&"); };
  var strip = function (h) { return ent(String(h || "").replace(/<[^>]+>/g, "")).trim(); };
